def best_path(paths, row=None, col=None, use_max=False, penalty=0, dtw_settings=None):
    """Compute the optimal path from the nxm warping paths matrix.

    :param paths: Warping paths matrix
    :param row: If given, start from this row (instead of lower-right corner)
    :param col: If given, start from this column (instead of lower-right corner)
    :param use_max: Find maximal path instead of minimal path
    :param penalty: The penalty used.
        If this is used, then paths should be expressed as the internal representation.
    :return: Array of (row, col) or (ts_1_idx, ts_2_idx) representing the best path
    """
    if use_max:
        argm = argmax
    else:
        argm = argmin
    if row is None:
        i = int(paths.shape[0] - 1)
    else:
        i = row
    if col is None:
        j = int(paths.shape[1] - 1)
    else:
        j = col
    p = []
    if paths[i, j] != -1:
        p.append((i - 1, j - 1))
    else:
        # Igore -1 at and of path
        if paths[i - 1, j] == -1:
            i -= 1
            while paths[i, j] == - 1 and i > 0:
                i -= 1
        elif paths[i, j - 1] == -1:
            j -= 1
            while paths[i, j] == -1 and j > 0:
                j -= 1
        else:
            if dtw_settings is not None:
                _, psi_1e, _, _ = dtw_settings.split_psi()
                if psi_1e == 0:
                    j -= 1
                else:
                    i -= 1
            else:
                i -= 1
        p.append((i - 1, j - 1))
    while i > 0 and j > 0:
        c = argm([paths[i - 1, j - 1],
                  paths[i - 1, j] + penalty,
                  paths[i, j - 1] + penalty])
        if c == 0:
            i, j = i - 1, j - 1
        elif c == 1:
            i = i - 1
        elif c == 2:
            j = j - 1
        p.append((i - 1, j - 1))
        if paths[i, j] == -1:
            # Igore -1 at begin of path
            break
    p.pop()
    p.reverse()
    return p

def warping_paths(*args, **kwargs):
    """
    Dynamic Time Warping (keep full matrix) using multidimensional sequences.

    See :py:meth:`dtaidistance.dtw.warping_paths` for parameters.
    """
    return dtw.warping_paths(*args, use_ndim=True, **kwargs)

